import math, urllib.request
LAT, LON = 39.029, -77.076   # Kensington, MD
txt = urllib.request.urlopen('https://noaa-ghcn-pds.s3.amazonaws.com/ghcnd-stations.txt').read().decode()
near = []
for line in txt.splitlines():
    sid, lat, lon = line[0:11], float(line[12:20]), float(line[21:30])
    d = math.hypot((lat - LAT) * 111, (lon - LON) * 111 * math.cos(math.radians(LAT)))
    if d < 25: near.append((round(d, 1), sid, line[41:71].strip()))
for d, sid, name in sorted(near)[:10]: print(d, sid, name)
